import shlex

import pytest

from shsplit import split_args


def oracle(s):
    return shlex.split(s, posix=True)


# --- Targeted tests reproducing each known symptom -------------------------

def test_consecutive_spaces():
    # Buggy: emits empty tokens between consecutive spaces
    assert split_args('a  b') == oracle('a  b') == ['a', 'b']


def test_leading_and_trailing_spaces():
    assert split_args(' a b ') == oracle(' a b ') == ['a', 'b']


def test_trailing_space_empty_token():
    # Buggy: trailing space adds an empty token
    assert split_args('a ') == oracle('a ') == ['a']


def test_backslash_escapes():
    # Buggy: backslash is treated as a literal character
    assert split_args(r'a\ b') == oracle(r'a\ b') == ['a b']
    assert split_args(r'it\'s "x\"y"') == oracle(r'it\'s "x\"y"') == ["it's", 'x"y']


def test_empty_quoted_string():
    # Buggy: standalone empty quoted string vanishes
    assert split_args('a "" b') == oracle('a "" b') == ['a', '', 'b']
    assert split_args("''") == oracle("''") == ['']


def test_quoting_basics():
    assert split_args("he said 'hi there'") == oracle("he said 'hi there'")
    assert split_args('"a b" c') == oracle('"a b" c') == ['a b', 'c']


# --- Seeded fuzz comparison against the oracle ------------------------------

import random


def _fuzz_strings(n=300, seed=42):
    rng = random.Random(seed)
    alphabet = list('abc xyz') + ['"', "'", '\\']
    cases = []
    for _ in range(n):
        length = rng.randint(0, 12)
        s = ''.join(rng.choice(alphabet) for _ in range(length))
        cases.append(s)
    return cases


@pytest.mark.parametrize('s', _fuzz_strings())
def test_fuzz_matches_shlex(s):
    try:
        expected = oracle(s)
    except ValueError:
        # Unbalanced quote: shlex rejects it; skip these inputs.
        pytest.skip('unbalanced quotes (shlex raises ValueError)')
    assert split_args(s) == expected

