"""Shell-style argument splitter matching shlex.split(s, posix=True).

POSIX rules implemented:
- Unquoted whitespace separates arguments; runs of spaces never yield
  empty tokens.
- Backslash escapes the next character outside quotes. Inside double
  quotes it only escapes '\\' and '"'; elsewhere the backslash is kept
  literally. A trailing backslash is an error ("no escaped character").
- Single quotes preserve everything until the closing quote.
- Empty quoted strings ('' / "") produce an empty argument.
- Unterminated quotes raise ValueError("no closing quotation"), mirroring
  shlex so callers can detect malformed input.
"""


def split_args(s):
    out, cur, started = [], '', False
    q = None      # active quote char ('"' or "'") or None
    esc = False   # previous char was a meaningful backslash
    i = 0
    while i < len(s):
        ch = s[i]
        if q:
            started = True
            if esc:
                # Inside double quotes a backslash only escapes \ and ".
                if q == '"' and ch not in '\\"':
                    cur += '\\'
                cur += ch
                esc = False
            elif ch == '\\':
                esc = True
            elif ch == q:
                q = None
            else:
                cur += ch
        elif esc:
            if ch == '\n':
                pass  # line continuation
            else:
                cur += ch
                started = True
            esc = False
        elif ch == '\\':
            esc = True
        elif ch in '"\'':
            q = ch
            started = True  # even an empty quoted string starts a token
        elif ch == ' ':
            if started:
                out.append(cur)
            cur, started = '', False
        else:
            cur += ch
            started = True
        i += 1

    if esc:
        raise ValueError('no escaped character')
    if q:
        raise ValueError('no closing quotation')
    if started:
        out.append(cur)
    return out

